This program is built with the standard gc compiler for linux/amd64. What does it print?

package main

import (
	"fmt"
	"unsafe"
)

type A struct {
	x bool
	y int64
	z bool
}

type B struct {
	y int64
	x bool
	z bool
}

func main() {
	fmt.Println(unsafe.Sizeof(A{}), unsafe.Sizeof(B{}))
}
